function C:FetchBody()
  repeat
    local __sw1 = Settings.CurrentLanguage.Value
    if __sw1 == "JP" then
      self._bodyText.text = self.tweetDrawable.BodyJp
    elseif __sw1 == "CN" then
      self._bodyText.text = self.tweetDrawable.BodyCn
    elseif __sw1 == "KO" then
      self._bodyText.text = self.tweetDrawable.BodyKo
    elseif __sw1 == "TW" then
      self._bodyText.text = self.tweetDrawable.BodyTw
    elseif __sw1 == "VN" then
      self._bodyText.text = self.tweetDrawable.BodyVn
    elseif __sw1 == "FR" then
      self._bodyText.text = self.tweetDrawable.BodyFr
    elseif __sw1 == "IT" then
      self._bodyText.text = self.tweetDrawable.BodyIt
    elseif __sw1 == "GE" then
      self._bodyText.text = self.tweetDrawable.BodyGe
    elseif __sw1 == "SP" then
      self._bodyText.text = self.tweetDrawable.BodySp
    elseif __sw1 == "RU" then
      self._bodyText.text = self.tweetDrawable.BodyRu
    else
      self._bodyText.text = self.tweetDrawable.BodyEn
    end
  until true
end

function C:FetchTweetImage()
  if not coroutine.isyieldable() then spawn(C.FetchTweetImage, self) return end
  local hasImage = NgoEx.IsNotEmpty(self.tweetDrawable.ImageId)
  self._image.gameObject:SetActive(hasImage)
  if hasImage then
    local imageId = self.tweetDrawable.ImageId
    local resource = self._resourceMaster.ResourceList:FirstOrDefault(function(r) return r.FileName == imageId end)
    Settings:addImage(imageId, true)
    if resource == nil then
      Debug.LogError(CONCAT(CONCAT(CONCAT("TWEET MASTER: ", imageId), " の 画像Id がなかったよ "), imageId))
      return false
    end
    local image = self._image
    image.sprite = LoadPictures.LoadPictureAsync(resource.FileName, "Poketter")
    if imageId == "MV_thumbnail" then
      local component = self._image.gameObject:GetComponent("Button")
      component:OnClickAsObservable():Subscribe(function(_)
        self:PlayMV()
      end):AddTo(component.gameObject)
      return true
    end
    local component2 = self._image.gameObject:GetComponent("Button")
    component2:OnClickAsObservable():Subscribe(function(_)
      spawn(function() ImageViewerHelper.OpenImageViewer(resource.FileName) end)
    end):AddTo(component2.gameObject)
  end
  return hasImage
end

function C:PlayMV()
  if not coroutine.isyieldable() then spawn(C.PlayMV, self) return end
  local videoViewer = GameObject.Find("Main Camera"):GetComponent("VideoPlayer")
  videoViewer.clip = Resources.Load("VideoClip", "Videos/INTERNETOVERDOSE")
  videoViewer:Prepare()
  videoViewer.aspectRatio = "FitInside"
  videoViewer:SetDirectAudioVolume(0, Settings.BgmVolume)
  AudioManager:StopBgm()
  videoViewer.targetCameraAlpha = 1
  videoViewer:Play()
  NgoEvent.DelaySkippable(2000)
  AudioManager:PlayBgmByType("BGM_InternetOverdose", false)
  self._baseCanvasGroup.interactable = false
  NgoEvent.DelaySkippable(224000)
  videoViewer.targetCameraAlpha = 0
  videoViewer:Stop()
  AudioManager:PlayBgmByType("BGM_InternetOverdose8bit", true)
  self._baseCanvasGroup.interactable = true
  videoViewer.aspectRatio = "FitHorizontally"
end

function C:Show()
  if not coroutine.isyieldable() then spawn(C.Show, self) return end
  self._baseCanvasGroup.alpha = 0
  local component = self:GetComponent("RectTransform")
  component.localScale = NEW("Vector3", nil, 1, 0, 1)
  local duration = self._scrollMillisecond / 1000
  local fade = self._fadeMillisecond / 1000
  self.gameObject:GetCancellationTokenOnDestroy()
  component:DOScaleY(1, duration):Play()
  self._baseCanvasGroup:DOFade(1, fade):Play()
  NgoEvent.DelaySkippable(STR.Length(self._bodyText.text) * 10)
end

function C:ConvertGigaNumber(number)
  if number > 1000000000 then
    return (TOSTR(IDIV(number, 100000000)) .. "G")
  end
  if number > 1000000 then
    return (TOSTR(IDIV(number, 100000)) .. "M")
  end
  if number > 10000 then
    return (TOSTR(IDIV(number, 1000)) .. "K")
  end
  return TOSTR(number)
end

function C:FavRtMove()
  if not self.tweetDrawable.IsOmote then
    return
  end
  local duration = self._buzzMillisecond / 1000
  if self.tweetDrawable.RtNumber > 0 then
    self._rtText:DOCounter(0, self.tweetDrawable.RtNumber, duration, true):OnComplete(function()
      self._rtText.text = self:ConvertGigaNumber(self.tweetDrawable.RtNumber)
    end):Play()
  end
  if self.tweetDrawable.FavNumber > 0 then
    self._favText:DOCounter(0, self.tweetDrawable.FavNumber, duration, true):OnComplete(function()
      self._favText.text = self:ConvertGigaNumber(self.tweetDrawable.FavNumber)
    end):Play()
  end
end

function C:SetKusoRep()
  for _, kusoRep in EACH(self.tweetDrawable.kusoReps) do
    Object.Instantiate(self._kusoRepPrefab, self._kusoRepRoot.transform):SetData(kusoRep)
  end
end

function C:SetKusoRepStatic()
  for _, kusoRep in EACH(self.tweetDrawable.kusoReps) do
    local kusoRepView = Object.Instantiate(self._kusoRepPrefab, self._kusoRepRoot.transform)
    kusoRepView:SetData(kusoRep)
    kusoRepView:ShowPosted()
  end
end

function C:ShowKusoReps()
  if not coroutine.isyieldable() then spawn(C.ShowKusoReps, self) return end
  if self._kusoRepRoot.childCount ~= 0 then
    NgoEvent.DelaySkippable(Constants.MIDDLE)
  end
  do
    local i = 0
    while i < self._kusoRepRoot.childCount do
      self._kusoRepRoot:GetChild(i):GetComponent("KusoRepView"):Show()
      i = i + 1
    end
  end
end

